72	
73	@RestController
74	@CrossOrigin(exposedHeaders = "errors, content-type")
75	@RequestMapping("/api")
76	public class OwnerRestControllerV1 implements OwnersApi {
77	
78	    private final ClinicService clinicService;
79	
80	    private final OwnerMapper ownerMapper;
81	
82	    private final PetMapper petMapper;
83	
84	    private final VisitMapper visitMapper;
85	
86	    private final OwnerFieldsValidator ownerFieldsValidator;
87	
88	    private final PostcodeValidator postcodeValidator;
89	
90	    private final RegistrationDateValidator registrationDateValidator;
91	
92	    private final HouseholdDuplicateValidator householdDuplicateValidator;
93	
94	    private final IdentityDuplicateValidator identityDuplicateValidator;
95	
96	    private final PossibleDuplicateDetector possibleDuplicateDetector;
97	
98	    private final HouseholdIdGenerator householdIdGenerator;
99	
100	    private final TelephoneNormalizer telephoneNormalizer;
101	
102	    private final EmailNormalizer emailNormalizer;
103	
104	    private final AddressNormalizer addressNormalizer;
105	
106	    private final CustomerCodeGenerator customerCodeGenerator;
107	
108	    private final NamesakeCounter namesakeCounter;
109	
110	    private final BulkSignupWarningEvaluator bulkSignupWarningEvaluator;
111	
112	    private final OwnerAuditLogger ownerAuditLogger;
113	
114	    public OwnerRestControllerV1(ClinicService clinicService,
115	                                 OwnerMapper ownerMapper,
116	                                 PetMapper petMapper,
117	                                 VisitMapper visitMapper,
118	                                 OwnerFieldsValidator ownerFieldsValidator,
119	                                 PostcodeValidator postcodeValidator,
120	                                 RegistrationDateValidator registrationDateValidator,
121	                                 HouseholdDuplicateValidator householdDuplicateValidator,
122	                                 IdentityDuplicateValidator identityDuplicateValidator,
123	                                 PossibleDuplicateDetector possibleDuplicateDetector,
124	                                 HouseholdIdGenerator householdIdGenerator,
125	                                 TelephoneNormalizer telephoneNormalizer,
126	                                 EmailNormalizer emailNormalizer,
127	                                 AddressNormalizer addressNormalizer,
128	                                 CustomerCodeGenerator customerCodeGenerator,
129	                                 NamesakeCounter namesakeCounter,
130	                                 BulkSignupWarningEvaluator bulkSignupWarningEvaluator,
131	                                 OwnerAuditLogger ownerAuditLogger) {
132	        this.clinicService = clinicService;
133	        this.ownerMapper = ownerMapper;
134	        this.petMapper = petMapper;
135	        this.visitMapper = visitMapper;
136	        this.ownerFieldsValidator = ownerFieldsValidator;
137	        this.postcodeValidator = postcodeValidator;
138	        this.registrationDateValidator = registrationDateValidator;
139	        this.householdDuplicateValidator = householdDuplicateValidator;
140	        this.identityDuplicateValidator = identityDuplicateValidator;
141	        this.possibleDuplicateDetector = possibleDuplicateDetector;
142	        this.householdIdGenerator = householdIdGenerator;
143	        this.telephoneNormalizer = telephoneNormalizer;
144	        this.emailNormalizer = emailNormalizer;
145	        this.addressNormalizer = addressNormalizer;
146	        this.customerCodeGenerator = customerCodeGenerator;
147	        this.namesakeCounter = namesakeCounter;
148	        this.bulkSignupWarningEvaluator = bulkSignupWarningEvaluator;
149	        this.ownerAuditLogger = ownerAuditLogger;
150	    }
151	
152	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
153	    @Override
154	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
155	        Collection<Owner> owners;
156	        if (lastName != null) {
157	            owners = this.clinicService.findOwnerByLastName(lastName);
158	        } else {
159	            owners = this.clinicService.findAllOwners();
160	        }
161	        if (owners.isEmpty()) {
162	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
163	        }
164	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
165	    }
166	
167	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
168	    @Override
169	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
170	        Owner owner = this.clinicService.findOwnerById(ownerId);
171	        if (owner == null) {
172	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
173	        }
174	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
175	    }
176	
177	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
178	    @Override
179	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
180	        if (ownerFieldsDto != null) {
181	            ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
182	        }
183	        List<String> missingFields = ownerFieldsValidator.findMissingOrBlankFields(ownerFieldsDto);
184	        if (!missingFields.isEmpty()) {
185	            throw new MissingOwnerFieldsException(missingFields);
186	        }
187	        HttpHeaders headers = new HttpHeaders();
188	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
189	        Collection<Owner> sameLastName =
190	            this.clinicService.findOwnersByLastNameIgnoreCase(owner.getLastName());
191	        owner.setNamesakeCount(namesakeCounter.count(owner, sameLastName));
192	        List<Owner> householdMembers = assignHousehold(owner, ownerFieldsDto, sameLastName);
193	        owner.setTelephone(telephoneNormalizer.normalize(owner.getTelephone()));
194	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
195	        postcodeValidator.validate(owner.getPostcode(), owner.getCity());
196	        rejectIfDuplicateIdentity(owner);
197	        flagPossibleDuplicate(owner, sameLastName);
198	        joinHousehold(owner, householdMembers);
199	        registrationDateValidator.validate(owner.getRegistrationDate());
200	        if (owner.getRegistrationDate() == null) {
201	            owner.setRegistrationDate(LocalDate.now());
202	        }
203	        owner.setRegistrationDate(BusinessDayResolver.toBusinessDay(owner.getRegistrationDate()));
204	        LocalDate registrationDate = owner.getRegistrationDate();
205	        long ownersRegisteredToday = clinicService.countOwnersByRegistrationDate(registrationDate);
206	        if (ownersRegisteredToday >= DailyOwnerLimitException.MAX_OWNERS_PER_DAY) {
207	            throw new DailyOwnerLimitException(registrationDate);
208	        }
209	        owner.setBulkSignupWarning(bulkSignupWarningEvaluator.isBulkSignup(ownersRegisteredToday));
210	        long cityOwnerCount = clinicService.countOwnersByCity(owner.getCity());
211	        if (cityOwnerCount >= CityOwnerLimitException.MAX_OWNERS_PER_CITY) {
212	            throw new CityOwnerLimitException(owner.getCity());
213	        }
214	        String region = LocalityResolver.localityOf(owner.getPostcode(), owner.getCity());
215	        owner.setCustomerCode(customerCodeGenerator.generate(
216	            region, owner.getTelephone(), owner.getLastName()));
217	        this.clinicService.saveOwner(owner);
218	        ownerAuditLogger.ownerCreated(owner);
219	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
220	        headers.setLocation(UriComponentsBuilder.newInstance()
221	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
222	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
223	    }
224	
225	    /**
226	     * Assigns the household attributes of an owner about to be created, without touching any
227	     * existing owner. The new owner's household size after this create is recorded (the existing
228	     * members that share its last name and address, compared case-insensitively with collapsed
229	     * whitespace, plus the owner itself). When the owner shares a household with an existing one
230	     * and the request opted in via {@code sharesHousehold}, the new owner is stamped with the
231	     * household's stable {@code householdId}.
232	     *
233	     * <p>Sharing a household is no longer a rejection in itself: duplicate detection is decided
234	     * solely by the derived identity key in {@link #rejectIfDuplicateIdentity(Owner)}. Because the
235	     * telephone is part of that key, household members with different telephones are all allowed.
236	     *
237	     * @return the existing household members that the new owner joins (empty when it starts a new
238	     *         household or does not opt in)
239	     */
240	    private List<Owner> assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto, Collection<Owner> sameLastName) {
241	        List<Owner> members = householdDuplicateValidator.findHouseholdMembers(owner, sameLastName);
242	        owner.setHouseholdSize(members.size() + 1);
243	        if (members.isEmpty() || !Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
244	            return List.of();
245	        }
246	        owner.setHouseholdId(householdIdGenerator.generate(owner));
247	        return members;
248	    }
249	
250	    /**
251	     * Stamps every existing member the new owner joins with the owner's {@code householdId}, so
252	     * the whole household shares one identifier. Called only once the owner has cleared duplicate
253	     * detection, so no existing owner is mutated for a create that is going to be rejected.
254	     */
255	    private void joinHousehold(Owner owner, List<Owner> members) {
256	        String householdId = owner.getHouseholdId();
257	        for (Owner member : members) {
258	            if (!householdId.equals(member.getHouseholdId())) {
259	                member.setHouseholdId(householdId);
260	                this.clinicService.saveOwner(member);
261	            }
262	        }
263	    }
264	
265	    /**
266	     * Rejects the owner when its whole derived {@link IdentityKey} already belongs to another
267	     * owner. A full-key match requires an equal telephone, so only owners with the same
268	     * (already normalized) telephone are compared.
269	     *
270	     * @throws DuplicateIdentityException if an existing owner shares the new owner's identity key
271	     */
272	    private void rejectIfDuplicateIdentity(Owner owner) {
273	        Collection<Owner> sameTelephone = this.clinicService.findOwnersByTelephone(owner.getTelephone());
274	        if (identityDuplicateValidator.isDuplicate(owner, sameTelephone)) {
275	            throw new DuplicateIdentityException(IdentityKey.of(owner));
276	        }
277	    }
278	
279	    /**
280	     * Flags the owner as a soft (possible) duplicate when it is not a hard duplicate yet shares an
281	     * existing owner's last name and postcode with a different telephone. The matching owner's id
282	     * is recorded in {@code possibleDuplicateOf}; when nothing matches the owner is stamped as not
283	     * a possible duplicate. Called after {@link #rejectIfDuplicateIdentity(Owner)}, so any candidate
284	     * seen here is guaranteed not to be a hard duplicate.
285	     */
286	    private void flagPossibleDuplicate(Owner owner, Collection<Owner> sameLastName) {
287	        Owner match = possibleDuplicateDetector.findPossibleDuplicate(owner, sameLastName).orElse(null);
288	        owner.setPossibleDuplicate(match != null);
289	        owner.setPossibleDuplicateOf(match == null ? null : match.getId());
290	    }
291	
292	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
293	    @Override
294	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
295	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
296	        if (currentOwner == null) {
297	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
298	        }
299	        currentOwner.setAddress(ownerFieldsDto.getAddress());
300	        currentOwner.setCity(ownerFieldsDto.getCity());
301	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
302	        currentOwner.setLastName(ownerFieldsDto.getLastName());
303	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
304	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
305	        this.clinicService.saveOwner(currentOwner);
306	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
307	    }
308	
309	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
310	    @Transactional
311	    @Override
312	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
313	        Owner owner = this.clinicService.findOwnerById(ownerId);
314	        if (owner == null) {
315	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
316	        }
317	        this.clinicService.deleteOwner(owner);
318	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
319	    }
