342	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
343	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
344	        if (currentOwner != null) {
345	            Pet currentPet = this.clinicService.findPetById(petId);
346	            if (currentPet != null) {
347	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
348	                currentPet.setName(petFieldsDto.getName());
349	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
350	                this.clinicService.savePet(currentPet);
351	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
352	            }
